<?php
declare(strict_types=1);
namespace BYPCMS\Core;

require_once __DIR__.'/Content.php';
require_once __DIR__.'/Journal.php';

/** Photo-led Content presentation. Records, permissions and storage belong to Content. */
final class Focus {
    private static function text(array $query,string $key,int $limit=120):string {
        return is_scalar($query[$key]??'')?mb_substr(trim((string)($query[$key]??'')),0,$limit):'';
    }
    private static function publicRecord(array $p):bool {
        $status=$p['status']??'published';$date=$p['published_at']??'';
        return in_array($status,['published','scheduled'],true)&&($date!==''?strtotime($date.' UTC')!==false&&strtotime($date.' UTC')<=time():$status==='published');
    }
    private static function imageUrl(string $url):string {
        return preg_match('#^(?:/(?!/)|https?://|data:image/)#i',$url)?Content::imageUrl($url):'';
    }
    public static function images():void {
        $root=defined('BYPCMS_SITE_ROOT')?BYPCMS_SITE_ROOT:dirname(__DIR__);
        $file=$root.'/themes/focus/media.json';
        if(defined('BYPCMS_SITE_ROOT')&&class_exists(UpdateRuntime::class)&&($p=UpdateRuntime::pointer($root)))$file=$root.'/_update-assets/'.$p['release'].'/_next/static/focus/media.json';
        if(is_file($file))foreach(json_decode((string)file_get_contents($file),true)??[]as $url=>$image)Content::$images[$url]=$image;
    }
    public static function feed(array $pages,array $settings,string $base=''):void {
        header('Content-Type: application/rss+xml; charset=utf-8');
        $e=static fn($s)=>htmlspecialchars((string)$s,ENT_XML1|ENT_QUOTES,'UTF-8');$site=rtrim(Content::url($settings['site_url']??''),'/').$base;
        echo '<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>'.$e($settings['site_name']??'Focus').'</title><link>'.$e($site.'/').'</link><description>'.$e($settings['tagline']??'').'</description><language>ru</language>';
        $rows=array_values(array_filter($pages,fn($p)=>($p['kind']??'page')==='article'&&self::publicRecord($p)));
        usort($rows,fn($a,$b)=>strcmp($b['published_at']??'',$a['published_at']??''));
        foreach(array_slice($rows,0,30)as $p){$url=$site.'/'.trim($p['slug'],'/').'/';echo '<item><title>'.$e($p['title']).'</title><link>'.$e($url).'</link><guid>'.$e($url).'</guid><description>'.$e($p['excerpt']??'').'</description>';if(!empty($p['published_at'])&&strtotime($p['published_at'])!==false)echo '<pubDate>'.gmdate(DATE_RSS,strtotime($p['published_at'].' UTC')).'</pubDate>';echo '</item>';}
        echo '</channel></rss>';
    }
    public static function mediaUrls(array $page):array {
        $out=[$page['cover']??''];$html=Content::html($page['content']??'').Content::blocks($page['blocks']??[]);
        preg_match_all('#<img\b[^>]*\bsrc="([^"]+)"#i',$html,$matches);
        foreach($matches[1]as $url)$out[]=html_entity_decode($url,ENT_QUOTES,'UTF-8');
        return array_slice(array_values(array_unique(array_filter($out,fn($url)=>self::imageUrl($url)!==''))),0,60);
    }
    private static function photo(string $url,string $alt,string $sizes,bool $eager=false):string {
        $url=self::imageUrl($url);if(!$url)return '<span class="f-no-photo" aria-hidden="true">F.</span>';
        $im=Content::$images[$url]??[];$e=[Content::class,'e'];
        return '<img src="'.$e(Content::asset($url)).'"'.(str_starts_with($url,'data:')?'':Content::imageSet($url,$sizes)).' width="'.max(1,(int)($im['width']??1200)).'" height="'.max(1,(int)($im['height']??800)).'" alt="'.$e($alt).'" '.($eager?'fetchpriority="high"':'loading="lazy"').' decoding="async">';
    }
    /** Object-fit cover needs enough pixels for the tall image, not just the viewport width. */
    private static function heroSizes(string $url):string {
        $im=Content::$images[$url]??[];$ratio=max(1,(int)($im['width']??1200))/max(1,(int)($im['height']??800));
        $mobile=(int)ceil(655*$ratio);$minimum=(int)ceil(650*$ratio);$maximum=(int)ceil(710*$ratio);$vh=number_format(78*$ratio,3,'.','');
        return '(max-width:760px) max(100vw, '.$mobile.'px), max(100vw, min('.$maximum.'px, '.$vh.'vh), '.$minimum.'px)';
    }
    /** Enhance only sanitized content; native image links also work without JavaScript. */
    public static function body(array $page):array {
        $photos=[];$cover=self::imageUrl($page['cover']??'');if($cover)$photos[$cover]=['index'=>1,'caption'=>$page['cover_alt']??$page['title']];
        $html=Content::html($page['content']??'').Content::blocks($page['blocks']??[]);
        $dom=new \DOMDocument('1.0','UTF-8');$old=libxml_use_internal_errors(true);
        $dom->loadHTML('<?xml encoding="utf-8" ?><div id="focus-body">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD|LIBXML_NONET);libxml_clear_errors();libxml_use_internal_errors($old);
        $root=$dom->getElementById('focus-body');if(!$root)return ['html'=>'','photos'=>$photos,'toc'=>[]];
        $toc=[];$xpath=new \DOMXPath($dom);
        foreach($xpath->query('.//h2|.//h3',$root)as $heading){$id='focus-section-'.(count($toc)+1);$heading->setAttribute('id',$id);$toc[]=['id'=>$id,'title'=>$heading->textContent];}
        foreach(iterator_to_array($root->getElementsByTagName('img'))as $img){
            $url=self::imageUrl($img->getAttribute('src'));if(!$url){$img->parentNode->removeChild($img);continue;}
            $caption=$img->getAttribute('alt');$parent=$img->parentNode;
            if($parent instanceof \DOMElement&&$parent->tagName==='figure')foreach($parent->getElementsByTagName('figcaption')as $cap){if(trim($cap->textContent)!=='')$caption=$cap->textContent;break;}
            if($parent instanceof \DOMElement&&$parent->tagName==='a'&&!in_array($parent->getAttribute('href'),[$url,Content::asset($url)],true))continue;
            if(!isset($photos[$url])){if(count($photos)>=60)continue;$photos[$url]=['index'=>count($photos)+1,'caption'=>$caption];}
            $img->setAttribute('src',Content::asset($url));$im=Content::$images[$url]??[];
            $ratio=isset($im['width'],$im['height'])&&$im['height']>0?$im['width']/$im['height']:1.5;
            $link=$dom->createElement('a');$link->setAttribute('href',Content::asset($url));$link->setAttribute('class','f-photo-link');$link->setAttribute('data-focus-photo',(string)$photos[$url]['index']);$link->setAttribute('data-caption',$caption);$link->setAttribute('aria-label','Увеличить фотографию '.$photos[$url]['index'].($caption!==''?': '.mb_substr($caption,0,160):''));$link->setAttribute('style','--photo-ratio:'.number_format($ratio,5,'.',''));
            if($parent instanceof \DOMElement&&$parent->tagName==='a'){$parent->parentNode->replaceChild($link,$parent);}else $parent->replaceChild($link,$img);
            $link->appendChild($img);
            if(!empty($im['width'])&&!empty($im['height'])){$img->setAttribute('width',(string)$im['width']);$img->setAttribute('height',(string)$im['height']);}
            $set=str_starts_with($url,'data:')?'':Content::imageSet($url,'(max-width:760px) calc(100vw - 40px), 1000px');
            if($set){$fragment=new \DOMDocument();@$fragment->loadHTML('<img'.$set.'>');$source=$fragment->getElementsByTagName('img')->item(0);foreach(['srcset','sizes']as $attr)$img->setAttribute($attr,$source->getAttribute($attr));}
            $zoom=$dom->createElement('span','Рассмотреть ↗');$zoom->setAttribute('class','f-zoom-label');$zoom->setAttribute('aria-hidden','true');$link->appendChild($zoom);
        }
        $out='';foreach($root->childNodes as $child)$out.=$dom->saveHTML($child);
        return ['html'=>$out,'photos'=>$photos,'toc'=>$toc];
    }
    public static function render(array $pages,array $terms,array $settings,string $path,string $base='',bool $preview=false,string $snapshot=''):void {
        self::images();foreach(is_array($settings['_media_images']??null)?$settings['_media_images']:[]as $url=>$image)if(self::imageUrl($url)&&is_array($image))Content::$images[$url]=$image;$e=[Content::class,'e'];$path=trim($path,'/');
        if(!$preview)$pages=array_values(array_filter($pages,fn($p)=>self::publicRecord($p)));
        $q=self::text($_GET,'q',100);$category=self::text($_GET,'category');$sort=self::text($_GET,'sort')==='old'?'old':'new';$year=self::text($_GET,'year',4);$month=self::text($_GET,'month',2);$error='';
