        $cats=array_values(array_filter($terms,fn($t)=>$t['kind']==='category'));
        $find=static function(string $slug,string $kind)use($terms){foreach($terms as $t)if($t['slug']===$slug&&$t['kind']===$kind)return $t;return null;};
        $has=static function(string $slug)use($pages){foreach($pages as $p)if(($p['kind']??'page')==='page'&&trim($p['slug'],'/')===$slug)return true;return false;};
        $mode=$path===''?'home':($path==='articles'?'listing':($path==='search'?'search':'404'));$page=null;$term=null;$list=$articles;$title=$name;$description=$tagline;
        if(preg_match('#^(category|author)/([a-z0-9-]+)$#D',$path,$m)){$term=$find($m[2],$m[1]);if($term){$mode=$m[1];$list=array_values(array_filter($list,fn($p)=>($p[$m[1]]??'')===$term['slug']));$title=$term['title'];$description=$term['description']??'';}}
