        if($mode==='category')$category='';
        $archive=$mode==='listing'&&($_GET['archive']??'')==='1';
        if($mode==='listing')$title=$archive?'Архив историй':'Все истории';
        if($mode==='search'){
            $title=$q!==''?'Поиск: '.$q:'Найти свою историю';
            $list=array_values(array_filter($list,fn($p)=>$q!==''&&(isset($settings['_search_matches'])?in_array((int)$p['id'],$settings['_search_matches'],true):mb_stripos($p['title'].' '.($p['excerpt']??'').' '.strip_tags($p['content']??''),$q)!==false)));
            usort($list,fn($a,$b)=>(int)(mb_stripos($b['title'],$q)!==false)<=>(int)(mb_stripos($a['title'],$q)!==false));
        }
        if(in_array($mode,['listing','category','author','search'],true)){
            $list=array_values(array_filter($list,fn($p)=>!$error&&($category===''||($p['category']??'')===$category)&&($year===''||substr($p['published_at']??'',0,4)===$year)&&($month===''||substr($p['published_at']??'',5,2)===str_pad($month,2,'0',STR_PAD_LEFT))));if($sort==='old')$list=array_reverse($list);
        }
        $total=count($list);$pageCount=max(1,(int)ceil($total/8));$num=min($pageCount,max(1,(int)self::text($_GET,'page')));$status=$mode==='404'?404:($error?400:200);
        if($mode==='404'){$title='История не найдена';$description='Возможно, адрес изменился. Попробуйте поиск или откройте все истории.';}
        $canonical=Content::url($page['canonical']??'')?:$site.$base.'/'.($path?$path.'/':'');if(str_starts_with($canonical,'/'))$canonical=$site.$canonical;
        $canonicalQuery=array_filter(['page'=>$num>1?$num:null,'category'=>$category,'year'=>$year,'month'=>$month,'sort'=>$sort==='old'?'old':null],fn($v)=>$v!==null&&$v!=='');if(in_array($mode,['listing','category','author'],true)&&$canonicalQuery)$canonical.='?'.http_build_query($canonicalQuery);
        $accent=preg_match('/^#[a-f0-9]{6}$/i',$settings['accent']??'')?$settings['accent']:'#c7411f';$rgb=sscanf($accent,'#%02x%02x%02x');$luma=0;foreach($rgb as $i=>$v){$v/=255;$luma+=($v<=.04045?$v/12.92:(($v+.055)/1.055)**2.4)*[.2126,.7152,.0722][$i];}$onAccent=$luma>.179?'#121616':'#ffffff';
        $logo=self::imageUrl($settings['logo']??'');$private=$preview&&$base==='';$cover=$page['cover']??($articles[0]['cover']??'');
