        $meta=static function(array $p)use($e,$href,$find){$author=$find($p['author']??'','author');echo '<div class="f-meta">';if($author)echo '<a href="'.$e($href('/author/'.$author['slug'].'/')).'">'.$e($author['title']).'</a>';else echo '<span>Редакция</span>';echo '<time datetime="'.$e(substr($p['published_at']??'',0,10)).'">'.$e(!empty($p['published_at'])?Journal::date($p['published_at']):'Без даты').'</time></div>';};
        $card=static function(array $p,int $i=0)use($e,$href,$find,$meta,$highlight){$cat=$find($p['category']??'','category');$url=$href('/'.trim($p['slug'],'/').'/');echo '<article class="f-tile f-tile-'.($i%4).'"><a class="f-tile-image" href="'.$e($url).'">'.self::photo($p['cover']??'',$p['cover_alt']??$p['title'],'(max-width:760px) calc(100vw - 40px), 55vw').'<span class="f-tile-arrow" aria-hidden="true">↗</span></a><div class="f-tile-top"><span>'.$e($cat['title']??'История').'</span><span>'.str_pad((string)($i+1),2,'0',STR_PAD_LEFT).'</span></div><h2><a href="'.$e($url).'">'.$highlight($p['title']).'</a></h2><p>'.$highlight($p['excerpt']??'').'</p>';$meta($p);echo '</article>';};
        $years=array_unique(array_filter(array_map(fn($p)=>substr($p['published_at']??'',0,4),$articles)));if($year!==''&&preg_match('/^(19|20|21)[0-9]{2}$/D',$year)&&!in_array($year,$years,true))$years[]=$year;rsort($years);
        header('Content-Type: text/html; charset=utf-8');http_response_code($status);header("Content-Security-Policy: default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline'; font-src 'self'; script-src 'self'; frame-ancestors 'self'; base-uri 'none'; form-action 'self'");header('X-Content-Type-Options: nosniff');
        if($preview){header('X-Robots-Tag: noindex, nofollow, noarchive');header('Cache-Control: no-store');}
        ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title.($mode==='home'?'':' — '.$name)) ?></title><meta name="description" content="<?= $e($description) ?>"><meta name="robots" content="<?= $preview||!empty($page['noindex'])||$mode==='search'||$status!==200?'noindex,follow':'index,follow' ?>"><link rel="canonical" href="<?= $e($canonical) ?>"><meta property="og:type" content="<?= $mode==='article'?'article':'website' ?>"><meta property="og:title" content="<?= $e($title) ?>"><meta property="og:description" content="<?= $e($description) ?>"><meta property="og:url" content="<?= $e($canonical) ?>"><?php if($cover&&!str_starts_with($cover,'data:')): ?><meta property="og:image" content="<?= $e(str_starts_with($cover,'/')?$site.$cover:$cover) ?>"><?php endif ?><link rel="alternate" type="application/rss+xml" title="<?= $e($name) ?> RSS" href="<?= $e($href('/feed.xml')) ?>"><link rel="icon" href="<?= $e($asset('favicon.svg')) ?>"><link rel="stylesheet" href="<?= $e($asset('focus.css')) ?>?v=1.0.1"><script src="<?= $e($asset('focus.js')) ?>?v=1.0.1" defer></script><?php if(($settings['font']??'')!=='system'||($settings['focus_heading_font']??'manrope')!=='georgia'): ?><link rel="preload" href="<?= $e($asset('assets/manrope.woff2')) ?>" as="font" type="font/woff2" crossorigin><?php endif ?><style>:root{--f-accent:<?= $e($accent) ?>;--f-on-accent:<?= $e($onAccent) ?>;--f-body:<?= ($settings['font']??'')==='system'?'system-ui':'FocusSans' ?>;--f-heading:<?= ($settings['focus_heading_font']??'manrope')==='georgia'?'Georgia':'FocusSans' ?>}</style>
